2, 3.19),   # 1953-Sept.\n    (3, 3.06),   # 1953-Oct.\n    (4, 3.04),   # 1953-Nov.\n    (5, 2.96),   # 1953-Dec.\n    (6, 2.90),   # 1954-Jan.\n    (7, 2.85),   # 1954-Feb.\n    (8, 2.73),   # 1954-Mar.\n    (9, 2.70),   # 1954-Apr.\n    (10, 2.72),  # 1954-May\n    (11, 2.70),  # 1954-June\n    (12, 2.62),  # 1954-July\n    (13, 2.60),  # 1954-Aug.\n    (14, 2.64),  # 1954-Sept.\n    (15, 2.65),  # 1954-Oct.\n    (16, 2.68),  # 1954-Nov.\n    (17, 2.68),  # 1954-Dec.\n    (18, 2.77),  # 1955-Jan.\n    (19, 2.92),  # 1955-Feb.\n    (20, 2.92),  # 1955-Mar.\n    (21, 2.92),  # 1955-Apr.\n    (22, 2.91),  # 1955-May\n    (23, 2.91),  # 1955-June\n    (24, 2.96),  # 1955-July\n    (25, 3.02),  # 1955-Aug.\n    (26, 3.00),  # 1955-Sept.\n    (27, 2.96),  # 1955-Oct.\n    (28, 2.96),  # 1955-Nov.\n    (29, 2.97),  # 1955-Dec.\n    (30, 2.94),  # 1956-Jan.\n    (31, 2.93),  # 1956-Feb.\n    (32, 2.98),  # 1956-Mar.\n    (33, 3.10),  # 1956-Apr.\n    (34, 3.03),  # 1956-May\n    (35, 2.98),  # 1956-June\n]\n\n# Extract X (month index) and Y (yield)\nX = np.array([d[0] for d in data])\nY = np.array([d[1] for d in data])\n\n# Perform OLS regression manually\nn = len(X)\nsum_x = np.sum(X)\nsum_y = np.sum(Y)\nsum_xy = np.sum(X * Y)\nsum_x2 = np.sum(X ** 2)\n\n# Calculate slope (beta1) and intercept (beta0)\nbeta1 = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x ** 2)\nbeta0 = (sum_y - beta1 * sum_x) / n\n\nprint(f\"Number of observations: {n}\")\nprint(f\"Sum X: {sum_x}, Sum Y: {sum_y}\")\nprint(f\"Slope (beta1): {beta1}\")\nprint(f\"Intercept (beta0): {beta0}\")\nprint(f\"Regression equation: Y = {beta0} + {beta1} * X\")\n\n# Forecast for July 1956 (month index 36)\nx_forecast = 36\ny_forecast = beta0 + beta1 * x_forecast\n\nprint(f\"\\nForecast for month index {x_forecast} (July 1956): {y_forecast}\")\nprint(f\"Rounded to three decimal places: {round(y_forecast, 3)}\")\n\n# Verify using numpy polyfit\nslope, intercept = np.polyfit(X, Y, 1)\nprint(f\"\\nVerification usi