  # 1954-June\n    (12, 2.62),  # 1954-July\n    (13, 2.60),  # 1954-Aug.\n    (14, 2.64),  # 1954-Sept.\n    (15, 2.65),  # 1954-Oct.\n    (16, 2.68),  # 1954-Nov.\n    (17, 2.68),  # 1954-Dec.\n    (18, 2.77),  # 1955-Jan.\n    (19, 2.92),  # 1955-Feb.\n    (20, 2.92),  # 1955-Mar.\n    (21, 2.92),  # 1955-Apr.\n    (22, 2.91),  # 1955-May\n    (23, 2.91),  # 1955-June\n    (24, 2.96),  # 1955-July\n    (25, 3.02),  # 1955-Aug.\n    (26, 3.00),  # 1955-Sept.\n    (27, 2.96),  # 1955-Oct.\n    (28, 2.96),  # 1955-Nov.\n    (29, 2.97),  # 1955-Dec.\n    (30, 2.94),  # 1956-Jan.\n    (31, 2.93),  # 1956-Feb.\n    (32, 2.98),  # 1956-Mar.\n    (33, 3.10),  # 1956-Apr.\n    (34, 3.03),  # 1956-May\n    (35, 2.98),  # 1956-June\n]\n\n# Verify months\nmonths = [\"July 1953\", \"Aug 1953\", \"Sept 1953\", \"Oct 1953\", \"Nov 1953\", \"Dec 1953\",\n          \"Jan 1954\", \"Feb 1954\", \"Mar 1954\", \"Apr 1954\", \"May 1954\", \"June 1954\",\n          \"July 1954\", \"Aug 1954\", \"Sept 1954\", \"Oct 1954\", \"Nov 1954\", \"Dec 1954\",\n          \"Jan 1955\", \"Feb 1955\", \"Mar 1955\", \"Apr 1955\", \"May 1955\", \"June 1955\",\n          \"July 1955\", \"Aug 1955\", \"Sept 1955\", \"Oct 1955\", \"Nov 1955\", \"Dec 1955\",\n          \"Jan 1956\", \"Feb 1956\", \"Mar 1956\", \"Apr 1956\", \"May 1956\", \"June 1956\"]\n\nprint(\"Data verification:\")\nfor i, (idx, yld) in enumerate(data):\n    print(f\"{i}: {months[i]}: {yld}\")\n\n# Extract X (month index) and Y (yield)\nX = [d[0] for d in data]\nY = [d[1] for d in data]\n\n# Perform OLS regression manually\nn = len(X)\nsum_x = sum(X)\nsum_y = sum(Y)\nsum_xy = sum([x*y for x,y in zip(X,Y)])\nsum_x2 = sum([x**2 for x in X])\n\n# Calculate slope (beta1) and intercept (beta0)\nbeta1 = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x ** 2)\nbeta0 = (sum_y - beta1 * sum_x) / n\n\nprint(f\"\\nOLS Regression Results:\")\nprint(f\"n = {n}\")\nprint(f\"sum_x = {sum_x}\")\nprint(f\"sum_y = {sum_y}\")\nprint(f\"sum_xy = {sum_xy}\")\nprint(f\"sum_x2 = {sum_x2}\")\nprint(f\"beta1 (slope) = {beta1}\")\nprint(f\"beta0 (intercept) = {beta0}\")\n\n# R-squared calculation\ny_mean = sum_y / n\nss_tot = sum([(y - y_mean)**2 for y in Y])\nss_res = sum([(Y[i] - (beta0 + beta1 * X[i]))**2 for i in range(n)])\nr_squared = 1 - (ss_res / ss_tot)\nprint(f\"R-squared = {r_squared}\")\n\n# Forecast for July 1956 (month index 36)\nx_forecast = 36\ny_forecast = beta0 + beta1 * x_forecast\n\nprint(f\"\\n--- Forecast for July 1956 ---\")\nprint(f\"x = {x_forecast}\")\nprint(f\"y = {beta0} + {beta1} * {x_forecast} = {y_forecast}\")\nprint(f\"Rounded to 3 decimal places: {round(y_forecast, 3)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
